    /*
     * Assign a Customer
     * 
     * @param	parentId	UUID
     * @param	assignment 	Customer 
     * @return	Agreement
     */
    public Agreement assignCustomer( UUID parentId, Customer assignment ) {
	    LOGGER.info("assigning Customer as " + assignment.toString() );

	    Agreement parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( Customer.class, assignment.getCustomerId());

	    // ------------------------------------------
		// assign the Customer to the parent entity
		// ------------------------------------------ 
	    parentEntity.setCustomer( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

